INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q15211574', 'Aksumite–Persian Wars', 'The Aksumite–Persian wars were a series of pre-Islamic battles that took place in the 6th century, when the Kingdom of Aksum and the Sasanian Empire fought for control over South Arabia. Between 570 and 580 AD, two Persian invasions secured control over South Arabia, giving rise to the province of Sasanian Yemen.', 570, NULL, NULL, 578, NULL, NULL, 'year', '570–578', 41, 'https://en.wikipedia.org/wiki/Aksumite%E2%80%93Persian_wars'),
  ('Q15211837', 'Siege of Sanaa', 'The siege of Sanaa is a pre-Islamic battle fought in the 6th century by the Kingdom of Aksum and the Sasanian Empire, during the Aksumite–Persian wars. It took place when the Sasanian under general Vahrez besieged the Aksumite city of Sanaa in 570.', 570, NULL, NULL, NULL, NULL, NULL, 'year', '570', 37, 'https://en.wikipedia.org/wiki/Siege_of_Sanaa_(570)'),
  ('Q3696172', 'Battle of Zafar', 'The Battle of Zafar took place in 632 between Khalid ibn al-Walid, a companion of the Islamic prophet Muhammad, and a tribal chieftess called Salma. Khalid defeated her and she died on the battlefield.', 632, 10, NULL, NULL, NULL, NULL, 'month', 'October 632', 48, 'https://en.wikipedia.org/wiki/Battle_of_Zafar'),
  ('Q3049873', 'Capture of Aden', 'The Aden revolt of 1548 was a rebellion against Ottoman rule in Yemen, that was suppressed after Ottoman forces under Piri Reis arrived on 26 February 1548.', 1548, 2, 26, NULL, NULL, NULL, 'day', '26 February 1548', 51, 'https://en.wikipedia.org/wiki/Aden_Revolt'),
  ('Q6542875', 'Libyan Federation of Arab Republics referendum, 1971', 'A referendum on the Federation of Arab Republics was held in Libya on 1 September 1971, alongside simultaneous referendums in Egypt and Syria. The referendum was an attempt by Muammar Gaddafi to merge Libya, Egypt and Syria into a unified Arab state.', 1971, 9, 1, NULL, NULL, NULL, 'day', '1 September 1971', 39, 'https://en.wikipedia.org/wiki/1971_Libyan_Federation_of_Arab_Republics_referendum'),
  ('Q16126368', 'First Yemenite War', 'The First Yemenite War was a short military conflict between the Yemen Arab Republic (YAR; North Yemen) and the People''s Democratic Republic of Yemen (PDRY; South Yemen).', 1972, 9, 26, 1972, 10, 19, 'day', '26 September 1972 – 19 October 1972', 47, 'https://en.wikipedia.org/wiki/First_Yemenite_War'),
  ('Q12207429', 'NDF Rebellion', 'The NDF Rebellion, also known as the Central Regions war (Arabic: حرب المناطق الوسطى), was an uprising and civil war in the Yemen Arab Republic (North Yemen) by the National Democratic Front, under Yahya Shami, between 1978 and 1982.', 1978, NULL, NULL, 1982, NULL, NULL, 'year', '1978–1982', 34, 'https://en.wikipedia.org/wiki/NDF_Rebellion'),
  ('Q3504562', '1982 North Yemen earthquake', 'The 1982 North Yemen earthquake hit near the city of Dhamar, North Yemen (now part of Yemen) on December 13. Measuring 6.2 on the moment magnitude scale, with a maximum perceived intensity of VIII (Severe) on the Mercalli intensity scale, as many as 2,800 people were killed and another 1,500 injured.', 1982, 12, 13, NULL, NULL, NULL, 'day', '13 December 1982', 41, 'https://en.wikipedia.org/wiki/1982_North_Yemen_earthquake'),
  ('Q2461485', '1994 Summer War', 'The Yemeni civil war (Arabic: الحرب الأهلية اليمنية), also known as the Summer War of 1994 (Arabic: حرب صيف ١٩٩٤), was a civil war fought between the two Yemeni forces of the pro-union northern and the socialist separatist southern Yemeni states and their supporters. The war resulted in the defeat of the southern separatists and the reunification of Yemen, and the flight into exile of many leaders of the Yemeni Socialist Party (YSP) and other separatists.', 1994, 7, 7, 1994, 7, 7, 'day', '7 July 1994', 61, 'https://en.wikipedia.org/wiki/Yemeni_civil_war_(1994)'),
  ('Q3297462', 'Sana''a school shooting', 'The Sanaa school shooting was a school shooting where Mohammad Ahman al-Nazari killed six people in Sanaa, Yemen, on 30 March 1997. Nazari was convicted for the killings and sentenced to death.', 1997, 3, 30, NULL, NULL, NULL, 'day', '30 March 1997', 34, 'https://en.wikipedia.org/wiki/Sanaa_school_shooting'),
  ('Q286436', 'Al-Qaeda insurgency in Yemen', 'The Al-Qaeda insurgency in Yemen is an ongoing armed conflict between the Yemeni government, the United States and their allies, and al-Qaeda-affiliated groups in Yemen. It was formerly a part of the Global War on Terrorism.', 1998, 12, 30, NULL, NULL, NULL, 'day', '30 December 1998', 55, 'https://en.wikipedia.org/wiki/Al-Qaeda_insurgency_in_Yemen'),
  ('Q130754', '2004 Indian Ocean earthquake', 'On 26 December 2004, at 07:58:53 local time (UTC+7), a Mw 9.2–9.3 earthquake struck with its epicenter off the west coast of Aceh, in northern Sumatra, Indonesia. The undersea megathrust earthquake, known in the scientific community as the Sumatra–Andaman earthquake, was caused by a rupture along the fault boundary between the Burma plate and the Indian plate, and reached a maximum Mercalli intensity of IX in some areas.', 2004, 12, 26, NULL, NULL, NULL, 'day', '26 December 2004', 85, 'https://en.wikipedia.org/wiki/2004_Indian_Ocean_earthquake_and_tsunami'),
  ('Q632663', 'South Yemen insurgency', 'The South Yemen insurgency is a series of protests and attacks on government forces in southern Yemen since 27 April 2009. The insurgency comes amid the Shia insurgency in the country''s north as led by the Houthi communities.', 2009, 4, 27, NULL, NULL, NULL, 'day', '27 April 2009', 51, 'https://en.wikipedia.org/wiki/South_Yemen_insurgency'),
  ('Q1091576', 'Battle of Zinjibar', 'The battle of Zinjibar was fought between Yemeni government forces and the Islamist militant group Ansar al-Sharia in and around Zinjibar, the provincial capital of Abyan governorate. As the state was preoccupied with the Yemeni revolution, the resultant security vacuum in southern Yemen was capitalized on by al-Qaeda in the Arabian Peninsula (AQAP), which used a local insurgent front in Ansar al-Sharia to seize territory for the first time.', 2011, 5, 27, 2012, 6, 12, 'day', '27 May 2011 – 12 June 2012', 41, 'https://en.wikipedia.org/wiki/Battle_of_Zinjibar_(2011%E2%80%932012)'),
  ('Q4116455', 'Battle of Ta''izz', 'The Battle of Taiz erupted during the 2011 Yemeni Revolution, between forces loyal to Yemeni leader Ali Abdullah Saleh and opposition protesters, backed by armed tribesmen and defecting soldiers in the southwestern Yemeni city of Taiz.', 2011, 5, 28, 2011, 6, 7, 'day', '28 May 2011 – 7 June 2011', 37, 'https://en.wikipedia.org/wiki/Battle_of_Taiz'),
  ('Q4872225', 'Battle of Sa''dah', 'The battle of Saada was a military confrontation that erupted in March 2011 between Houthi rebels and tribal forces loyal to Yemeni President Ali Abdullah Saleh in the northern city of Saada. Following days of heavy clashes, the Houthis managed to capture the entire Saada Governorate including its provincial capital and established an independent administration, thereby marking the first such Yemeni governorate to fall out of central government control since the nationwide uprising began in 2011.', 2011, 3, 26, 2011, 3, 26, 'day', '26 March 2011', 37, 'https://en.wikipedia.org/wiki/Battle_of_Saada'),
  ('Q11163323', 'Siege of Dammaj', 'The siege of Dammaj began in October 2011 when the Houthis, a rebel group which controls the Saada Governorate, accused Salafis loyal to the Yemeni government of smuggling weapons into their religious center in the town of Dammaj and demanded they hand over their weapons and military posts in the town. As the Salafis refused, Houthi rebels responded by imposing a siege on Dammaj, closing the main entrances leading to the town.', 2011, 10, 15, 2011, 12, 22, 'day', '15 October 2011 – 22 December 2011', 37, 'https://en.wikipedia.org/wiki/Siege_of_Dammaj'),
  ('Q210005', '2011 Yemeni revolution', 'The Yemeni revolution, also known as the Yemeni intifada, was a series of major anti-government protests and armed uprisings that raged through Yemen from January 2011 to February 2012. It occurred concurrently with the Arab Spring that broke out throughout the Middle East and North Africa in 2011.', 2012, 2, 27, 2012, 2, 27, 'day', '27 February 2012', 70, 'https://en.wikipedia.org/wiki/Yemeni_revolution'),
  ('Q18821624', 'Battle of Amran', 'The battle of ''Amran was a battle that took place in July 2014 between the Houthi rebels and the Yemeni government of President Abdrabbuh Mansur Hadi. The government''s forces consisted of units belonging to the 310th Armored Brigade, which is backed by Al-Islah loyalists, of which the Al Ahmar clan of Hashid tribes hailed from.', 2014, 2, 2, 2014, 7, 10, 'day', '2 February 2014 – 10 July 2014', 37, 'https://en.wikipedia.org/wiki/Battle_of_Amran'),
  ('Q19121521', 'Battle of Sana''a (2014)', 'The Battle of Sanaa in 2014 marked the advance of the Houthis into Sanaa, the capital of Yemen, and heralded the beginning of the armed takeover of the government that unfolded over the following months. Fighting began on 9 September 2014, when pro-Houthi protesters under the command of Abdul-Malik al-Houthi marched on the cabinet office and were fired upon by security forces, leaving seven dead.', 2014, 9, 21, 2015, 3, 21, 'day', '21 September 2014 – 21 March 2015', 41, 'https://en.wikipedia.org/wiki/Battle_of_Sanaa_(2014)'),
  ('Q19686631', 'Yemeni Civil War', 'The Yemeni civil war (Arabic: الحرب الأهلية اليمنية, romanized: al-ḥarb al-ʾahlīyah al-yamanīyah) is an ongoing multilateral civil war that began in late 2014 mainly between the Rashad al-Alimi-led Presidential Leadership Council and the Mahdi al-Mashat-led Supreme Political Council, along with their respective supporters and allies. Both sides claim to constitute the official government of Yemen while the Presidential Leadership Council is recognized by the United Nations as the official government.', 2014, 9, 16, NULL, NULL, NULL, 'day', '16 September 2014', 78, 'https://en.wikipedia.org/wiki/Yemeni_civil_war_(2014%E2%80%93present)'),
  ('Q18145759', 'Houthi takeover in Yemen', 'The Houthi takeover in Yemen, also known by the Houthis as the September 21 Revolution, or 2014–15 Yemeni coup d''état (by opponents), was a popular revolution against Yemeni President Abdrabbuh Mansur Hadi led by the Houthis and their supporters that pushed the Yemeni government from power. It had origins in Houthi-led protests that began the previous month, and escalated when the Houthis stormed the Yemeni capital Sanaa on 21 September 2014, causing the resignation of Prime Minister Mohammed Basindawa, and later the resignation of President Abdrabbuh Mansur Hadi and his ministers on 22…', 2015, 2, 6, 2015, 2, 6, 'day', '6 February 2015', 52, 'https://en.wikipedia.org/wiki/Houthi_takeover_of_Yemen'),
  ('Q19637227', '2015 Sana''a mosque bombings', 'The 2015 Sanaa mosque bombings were four suicide attacks targeting two mosques on 20 March 2015 in Sanaa, Yemen.', 2015, 3, 20, NULL, NULL, NULL, 'day', '20 March 2015', 57, 'https://en.wikipedia.org/wiki/March_2015_Sanaa_mosque_bombings'),
  ('Q19637804', 'Battle of Aden Airport', 'The Battle of Aden International Airport broke out in the early morning hours of 19 March 2015, when Yemen Army units loyal to former president Ali Abdullah Saleh attacked the airport in Aden, Yemen. The airport was defended by soldiers and guards supporting Abdrabbuh Mansur Hadi, Yemen''s internationally recognised president.', 2015, 3, 19, NULL, NULL, NULL, 'day', '19 March 2015', 37, 'https://en.wikipedia.org/wiki/Battle_of_Aden_Airport'),
  ('Q19759389', 'Battle of Al Mukalla', 'The First Battle of Mukalla (2015) was a battle between al-Qaeda in the Arabian Peninsula, local tribesmen, and the Yemen Army for control of the coastal city of Mukalla, Yemen.', 2015, 4, 16, 2015, 4, 16, 'day', '16 April 2015', 37, 'https://en.wikipedia.org/wiki/Battle_of_Mukalla_(2015)'),
  ('Q19783940', 'Battle of Aden (2015)', 'The Battle of Aden was a nearly four-month battle in 2015 for the control of Aden, Yemen, between Houthi rebels and Yemen Army forces loyal to Ali Abdullah Saleh on one side, and Yemen Army units loyal to Abdrabbuh Mansur Hadi and Southern Movement militias on the other side. The battle began on 25 March 2015, as pro-Saleh troops seized control of Aden International Airport and Hadi fled the country by boat.', 2015, 7, 22, 2015, 7, 22, 'day', '22 July 2015', 39, 'https://en.wikipedia.org/wiki/Battle_of_Aden_(2015)'),
  ('Q19794605', 'Battle of Dhale', 'The Battle of Dhale was a key fight in 2015 for control of Dhale, Yemen, between the Houthis and Yemen Army units loyal to Ali Abdullah Saleh on one side, and militiamen and Yemen Army units loyal to Abd Rabbuh Mansur Hadi on the other side.', 2015, 5, 26, 2015, 5, 26, 'day', '26 May 2015', 37, 'https://en.wikipedia.org/wiki/Battle_of_Dhale'),
  ('Q22686517', 'September 2015 Marib Toshka missile attack', 'On 4 September 2015, the Houthis launched an OTR-21 Tochka ballistic missile against a military base in Safer, an area in Marib Governorate. The base was being used by military forces of the Saudi-led coalition.', 2015, NULL, NULL, NULL, NULL, NULL, 'year', '2015', 37, 'https://en.wikipedia.org/wiki/2015_Marib_attack'),
  ('Q28220588', 'famine in Yemen (2016–)', 'Since 2016, a food insecurity crisis has been ongoing in Yemen which began during the Yemeni civil war. The UN estimates that the war has caused an estimated 130,000 deaths from indirect causes which include lack of food, health services, and infrastructure as of December 2020.', 2016, NULL, NULL, NULL, NULL, NULL, 'year', '2016', 52, 'https://en.wikipedia.org/wiki/Famine_in_Yemen_(2016%E2%80%93present)'),
  ('Q28716912', 'raid on Yakla', 'The Raid on Yakla was a joint United States/United Arab Emirates military operation carried out on January 29, 2017 in al-Ghayil, a village in the Yakla area of the Al Bayda Governorate of central Yemen, during the Yemeni civil war. Prepared by U.S. counterterrorism officials under President Barack Obama, the mission was ultimately authorized by President Donald Trump nine days into his presidency.', 2017, 1, 29, NULL, NULL, NULL, 'day', '29 January 2017', 37, 'https://en.wikipedia.org/wiki/Raid_on_Yakla'),
  ('Q44407676', 'Battle of Sana''a', 'The Battle of Sanaa in 2017 was fought between forces loyal to Ali Abdullah Saleh and the Houthis in the Yemeni capital of Sanaa. Both sides were allied during the 2014–15 Houthi takeover of the government but the alliance ended when Saleh decided to break ranks with the Houthis and call for dialogue with Saudi Arabia and the United Arab Emirates, who are leading a military intervention in Yemen.', 2017, 11, 29, 2017, 12, 4, 'day', '29 November 2017 – 4 December 2017', 37, 'https://en.wikipedia.org/wiki/Battle_of_Sanaa_(2017)'),
  ('Q47510319', 'Battle of Aden (2018)', 'The Battle of Aden was a conflict between the Southern Transitional Council (STC) and the Yemeni government around the headquarters in Aden.', 2018, 1, 31, 2018, 1, 31, 'day', '31 January 2018', 43, 'https://en.wikipedia.org/wiki/Battle_of_Aden_(2018)'),
  ('Q48735086', 'Battle of Al Hudaydah', 'The siege of Hodeidah, also called Hudaydah or al-Hudaydah, (Arabic: معركة الحديدة, romanized: Ma‘rakat al-Ḥudaydah), codenamed Operation Golden Victory, was a major Saudi-led coalition assault on the port city of Hodeidah in Yemen. It was spearheaded by the United Arab Emirates and Saudi Arabia and was considered the largest battle since the start of the Saudi Arabian-led intervention in Yemen in 2015.', 2018, 9, 16, NULL, NULL, NULL, 'day', '16 September 2018', 41, 'https://en.wikipedia.org/wiki/Battle_of_Hodeidah'),
  ('Q66370931', '2019 Southern Yemen clashes', 'The Southern Yemen clashes were a series of clashes in the city of Aden between the pro-Hadi government troops backed by Saudi Arabia and Southern Transitional Council forces backed by the United Arab Emirates. The Southern Transitional Council took control of Aden and Zinjibar.', 2019, 8, 7, NULL, NULL, NULL, 'day', '7 August 2019', 34, 'https://en.wikipedia.org/wiki/2019_Southern_Yemen_clashes'),
  ('Q67184364', 'Battle of the Jabara Valley', 'The Battle of the Jabara Valley occurred between 26 and 29 August 2019, during the Second Yemeni Civil War. It was part of Operation Victory from God, a major Houthi-led offensive along the Saudi Arabian-Yemeni border.', 2019, 8, 26, 2019, 8, 29, 'day', '26 August 2019 – 29 August 2019', 34, 'https://en.wikipedia.org/wiki/Battle_of_the_Jabara_Valley'),
  ('Q96212103', 'al-Jawf Offensive', 'The Al Jawf offensive was a Houthi offensive that began in February 2020 with clashes in the Al Jawf Governorate during the Second Yemeni Civil War. Houthi forces were able to decisively capture the town of Al Hazm on 1 March 2020 from the Hadi government.', 2020, 2, 29, 2020, 4, 29, 'day', '29 February 2020 – 29 April 2020', 34, 'https://en.wikipedia.org/wiki/Al-Jawf_offensive'),
  ('Q122962941', 'Gaza War', 'The Gaza war is an armed conflict in the Gaza Strip and Israel, fought as part of the unresolved Israeli–Palestinian and Gaza–Israel conflicts. The war began on 7 October 2023, when Palestinian militant group Hamas led an attack on Israel, in which 1,195 Israelis and foreign nationals were killed and 251 were taken hostage.', 2020, NULL, NULL, NULL, NULL, NULL, 'decade', '2020s', 91, 'https://en.wikipedia.org/wiki/Gaza_war'),
  ('Q124254493', 'US–UK airstrikes on Yemen', 'Between 12 January 2024 and 6 May 2025 the United States and the United Kingdom, with support from Australia, Bahrain, Canada, Denmark, the Netherlands, and New Zealand, launched a series of cruise missile and airstrikes against the Houthi movement in Yemen in response to Houthi attacks on ships in the Red Sea. The Houthis had previously declared that their attacks were in support of Palestinians during the Gaza war; Houthi attacks on shipping were condemned by the United Nations Security Council the day before the initial strike.', 2024, 1, 12, NULL, NULL, NULL, 'day', '12 January 2024', 64, 'https://en.wikipedia.org/wiki/US%E2%80%93UK_airstrikes_on_Yemen'),
  ('Q133894632', '2025 Ras Isa oil terminal airstrikes', 'On 17 April 2025, the United States Air Force conducted 14 airstrikes on a key oil terminal in Ras Isa in Houthi-controlled Yemen. The strike killed at least 80 people and injured another 171, making it the deadliest attack in Yemen since the beginning of the March 2025 United States strikes on Yemen.', 2025, 4, 17, NULL, NULL, NULL, 'day', '17 April 2025', 34, 'https://en.wikipedia.org/wiki/2025_Ras_Isa_oil_terminal_airstrikes'),
  ('Q134437528', '2025 Saada prison airstrike', 'On 28 April 2025, airstrikes launched by the United States Air Force struck a migrant detention centre operated by the Houthis in the city of Saada in Saada Governorate, Yemen. The attacks left at least 68 detained African migrants dead and 47 others injured.', 2025, 4, 28, NULL, NULL, NULL, 'day', '28 April 2025', 37, 'https://en.wikipedia.org/wiki/2025_Saada_prison_airstrike'),
  ('Q137209864', '2025–2026 southern Yemen campaign', 'On 2 December 2025, during the Yemeni civil war, the Southern Transitional Council (STC)—a secessionist faction backed by the United Arab Emirates—launched a large-scale military offensive across southern Yemen, breaking years of military stalemate in the conflict. The operation began in the Hadhramaut Governorate, which at the time was under the control of the internationally recognized, Saudi-backed government of Yemen.', 2025, 12, 2, 2026, 1, 9, 'day', '2 December 2025 – 9 January 2026', 52, 'https://en.wikipedia.org/wiki/2025%E2%80%932026_southern_Yemen_campaign'),
  ('Q137757212', 'Fall of Aden', 'On 7 January 2026, the Yemeni government (Presidential Leadership Council, PLC) forces captured the Southern Transitional Council''s de facto capital, Aden, resulting in the STC''s reported dissolution and the collapse of the group''s forces in the area. The city''s capture was the culmination of a government counteroffensive against the STC that had previously captured Hadhramaut and al-Mahrah Governorates amid Saudi airstrikes against STC positions.', 2026, 1, 7, NULL, NULL, NULL, 'day', '7 January 2026', 45, 'https://en.wikipedia.org/wiki/Fall_of_Aden_(2026)'),
  ('Q141349562', '2026 Yemen offensives', '2026 military campaign in Yemen.', 2026, 9, 3, NULL, NULL, NULL, 'day', '3 September 2026', 55, 'https://en.wikipedia.org/wiki/2026_Yemen_offensives'),
  ('Q141655522', 'Operation Dawn of Yemen', 'On 3 September 2026, the Iran-backed Houthis launched an offensive against the Saudi-backed Presidential Leadership Council (PLC), the internationally recognized government of Yemen, amid the ongoing Yemeni civil war. Clashes began in Taiz Governorate, prompting a PLC counter-offensive against the Houthis in the Al-Jawf and Al-Bayda governorates.', 2026, 10, 5, NULL, NULL, NULL, 'day', '5 October 2026', 34, 'https://en.wikipedia.org/wiki/Operation_Dawn_of_Yemen');
